/// <summary>
/// Item query
/// </summary>
/// <param name = "_itemList">List of items</param>
/// <returns>List of items</returns>
[
    DataMemberAttribute('ItemList'),
    AifCollectionTypeAttribute(identifierStr(_itemList), Types::String, extendedTypeStr(ItemId)),
    SysOperationLabelAttribute(literalstr("@MET:ItemQuery")),
    SysOperationHelpTextAttribute(literalStr("@MET:ItemQuery"))
]
public List parmItemList(List _itemList = itemList)
{
    itemList = _itemList;
    return itemList;
}

